#include "current_numeric_guess.hpp"
#include <Eigen/QR>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <vector>
#include <cstdint>
std::uint64_t u(std::ifstream&f){std::uint64_t x;f.read(reinterpret_cast<char*>(&x),8);if(!f)throw std::runtime_error("truncated");return x;}
Eigen::MatrixXd mat(std::ifstream&f){auto r=u(f),c=u(f);if(r>20000||c>144)throw std::runtime_error("shape");Eigen::MatrixXd a(r,c);for(unsigned i=0;i<r;++i)for(unsigned j=0;j<c;++j)f.read(reinterpret_cast<char*>(&a(i,j)),8);return a;}
Eigen::VectorXd vec(std::ifstream&f){auto n=u(f);if(n>20000)throw std::runtime_error("shape");Eigen::VectorXd a(n);f.read(reinterpret_cast<char*>(a.data()),n*8);if(!f)throw std::runtime_error("truncated vector");return a;}
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("fixture partialxy stationaryfaces prefix");std::ifstream f(argv[1],std::ios::binary);auto H=mat(f);auto g=vec(f);auto A=mat(f);auto lo=vec(f);auto hi=vec(f);auto seed=vec(f);std::ifstream xy(argv[2],std::ios::binary);auto x=vec(xy);auto ignored=vec(xy);std::ifstream faces(argv[3],std::ios::binary);faces.seekg(0,std::ios::end);auto bytes=faces.tellg();if(bytes<=0||bytes%16||bytes/16>144)throw std::runtime_error("face bytes");faces.seekg(0);const int n=g.size(),k=bytes/16;Eigen::MatrixXd W(n,k);std::vector<int> rows,sides;for(int j=0;j<k;++j){std::int64_t row,side;faces.read(reinterpret_cast<char*>(&row),8);faces.read(reinterpret_cast<char*>(&side),8);if(row<0||row>=A.rows()||(side!=1&&side!=-1))throw std::runtime_error("faces");rows.push_back(row);sides.push_back(side);W.col(j)=side*A.row(row).transpose();}Eigen::VectorXd b=-(H*x+g);Eigen::MatrixXd K=Eigen::MatrixXd::Zero(n+k,n+k);K.topLeftCorner(n,n)=H;K.topRightCorner(n,k)=W;K.bottomLeftCorner(k,n)=W.transpose();Eigen::VectorXd rhs=Eigen::VectorXd::Zero(n+k);rhs.head(n)=b;phase5_working_face_basis_v1::Trace refinement;auto old=phase5_dynamic_numeric_v1::solveKkt(K,rhs,n,&refinement,511);std::cout<<std::setprecision(17)<<"old_KKT_rank="<<old.rank<<" dimension="<<old.dimension<<" direction_inf="<<old.value.head(n).lpNorm<Eigen::Infinity>()<<" minimum_lambda="<<old.value.tail(k).minCoeff()<<" original_KKT_residual="<<old.residual<<"\n";
 Eigen::VectorXd scale(k);Eigen::MatrixXd normalized=W;for(int j=0;j<k;++j){scale(j)=W.col(j).norm();if(scale(j)==0)scale(j)=1;normalized.col(j)/=scale(j);}Eigen::VectorXd coeff=Eigen::VectorXd::Zero(k);std::vector<unsigned char> passive(k,0);int solves=0,outer=0,inner_total=0;std::string error;const double internal_tol=1e-14;std::ofstream trace(std::string(argv[4])+".trace.txt");
 for(outer=0;outer<128;++outer){Eigen::VectorXd residual=b-normalized*coeff;const double norm=residual.lpNorm<Eigen::Infinity>();if(norm<=internal_tol)break;Eigen::VectorXd w=normalized.transpose()*residual;int chosen=-1;double peak=internal_tol;for(int j=0;j<k;++j)if(!passive[j]&&w(j)>peak){chosen=j;peak=w(j);}if(chosen<0){error="no inactive positive dual-gradient above internal search tolerance";break;}passive[chosen]=1;bool inner_complete=false;
  for(int inner=0;inner<256;++inner){if(++inner_total>512||solves>=512){error="finite512 total NNLS least-squares steps";break;}std::vector<int> ids;for(int j=0;j<k;++j)if(passive[j])ids.push_back(j);Eigen::MatrixXd M(n,ids.size());for(std::size_t j=0;j<ids.size();++j)M.col(j)=normalized.col(ids[j]);Eigen::VectorXd z=Eigen::VectorXd::Zero(k);++solves;if(!ids.empty()){Eigen::CompleteOrthogonalDecomposition<Eigen::MatrixXd> qr(M);Eigen::VectorXd value=qr.solve(b);if(!value.allFinite())throw std::runtime_error("nonfinite NNLS search solve");for(std::size_t j=0;j<ids.size();++j)z(ids[j])=value(j);}bool positive=true;for(int j:ids)if(z(j)<=0){positive=false;break;}trace<<outer<<" "<<inner<<" "<<ids.size()<<" "<<norm<<" "<<(b-normalized*z).lpNorm<Eigen::Infinity>()<<"\n";
   if(positive){coeff=z;inner_complete=true;break;}double alpha=1;int boundary=-1;for(int j:ids)if(z(j)<=0&&coeff(j)-z(j)>0){double fraction=coeff(j)/(coeff(j)-z(j));if(fraction<alpha){alpha=fraction;boundary=j;}}if(boundary<0){error="NNLS passive nonpositive solve without finite boundary";break;}coeff+=alpha*(z-coeff);coeff(boundary)=0;passive[boundary]=0;for(int j:ids)if(coeff(j)<=0){coeff(j)=0;passive[j]=0;}
  }
  if(!inner_complete){if(error.empty())error="finite256 inner NNLS steps";break;}
 }
 trace.close();Eigen::VectorXd lambda=coeff.array()/scale.array();Eigen::VectorXd full=Eigen::VectorXd::Zero(A.rows());for(int j=0;j<k;++j)full(rows[j])+=sides[j]*lambda(j);double violation=std::max({0.,(lo-A*x).maxCoeff(),(A*x-hi).maxCoeff()}),stat=(H*x+g+A.transpose()*full).lpNorm<Eigen::Infinity>();std::ofstream out(std::string(argv[4])+".certificate.bin",std::ios::binary);for(const auto*v:{&x,&lambda,&full}){std::uint64_t count=v->size();out.write(reinterpret_cast<char*>(&count),8);out.write(reinterpret_cast<const char*>(v->data()),8*count);}out.close();const bool cert=lambda.allFinite()&&lambda.minCoeff()>=-1e-12&&violation<=1e-12&&stat<=1e-10;std::cout<<"nonnegative_dual_certificate="<<cert<<" outer="<<outer<<" least_squares_solves="<<solves<<" inner_total="<<inner_total<<" lambda_min="<<lambda.minCoeff()<<" lambda_max="<<lambda.maxCoeff()<<" original_primal_violation="<<violation<<" original_full_stationarity="<<stat<<" normalized_residual="<<(b-normalized*coeff).lpNorm<Eigen::Infinity>()<<" search_error="<<std::quoted(error)<<" noModel_nativeOSQP_B_C_physics=1\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
